pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;
    SigMaker maker;
    MockERC20 base;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
        maker = new SigMaker();
        base = new MockERC20();
        vm.warp(1_000_000);
    }

    function testFuzz_property(
        uint256 premium,
        uint256 strike,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        address taker
    ) public {
        vm.assume(taker != address(0));
        vm.assume(taker != address(maker));
        vm.assume(taker != address(c));
        duration = bound(duration, 0, 9_999 days);
        expiration = bound(expiration, 1_000_001, 2_000_000_000);

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        PuttyV2.ERC20Asset[] memory erc20s = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721s = new PuttyV2.ERC721Asset[](0);
        uint256[] memory floorIds = new uint256[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(maker),
            isCall: true,
            isLong: false,
            baseAsset: address(base),
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20s,
            erc721Assets: erc721s
        });

        bytes memory sig = new bytes(0);

        vm.prank(taker);
        uint256 positionId = c.fillOrder(order, sig, floorIds);

        // General rule: a successful fill always returns the id of the taker's
        // own minted opposite position, uint256(hashOppositeOrder(order)).
        assertTrue(positionId == uint256(c.hashOppositeOrder(order)), "fillOrder must return opposite-order position id");
    }
}

contract SigMaker {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return 0x1626ba7e;
    }
}

contract MockERC20 {
    function transferFrom(address, address, uint256) external returns (bool) {
        return true;
    }
}
